<?php
declare(strict_types=1);
define('LCHAT_INTERNAL', true);
require dirname(__DIR__) . '/app.php';
$ctx=context(); ensure_features();
if(!$ctx['uid']){header('Location: ../index.php',true,302);exit;}
$user=require_user($ctx); $uid=(int)$user['id'];
$bot=one('SELECT u.id FROM users u JOIN bot_accounts b ON b.bot_user_id=u.id WHERE LOWER(u.username)=?', ['compilerbot']);
$chatId=0;
if($bot){$botId=(int)$bot['id'];$key=min($uid,$botId).':'.max($uid,$botId);$chat=one('SELECT id FROM chats WHERE direct_key=?',[$key]);if($chat)$chatId=(int)$chat['id'];else{$chatId=transaction(function()use($uid,$botId,$key){query('INSERT INTO chats(kind,title,owner_id,direct_key,created_at)VALUES(?,?,?,?,?)',['direct','',$uid,$key,stamp()]);$id=(int)db()->lastInsertId();foreach([$uid,$botId]as$who)query('INSERT INTO members(chat_id,user_id,role,joined_at)VALUES(?,?,?,?)',[$id,$who,'member',stamp()]);return$id;});}}
header('Cache-Control: no-store');
?>
