<script>const CHAT=<?=$chatId?>,ME=<?=$uid?>,CSRF=<?=json_encode($ctx['csrf'])?>;let files={},last=0,editCursor=0,busy=false;const $=id=>document.getElementById(id),nonce=()=>globalThis.crypto?.randomUUID?crypto.randomUUID().replaceAll('-',''):(Date.now().toString(36)+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2));async function json(url,options){const r=await fetch(url,options),d=await r.json();if(!r.ok)throw Error(d.error||d.description||'Ошибка');return d}async function siteLoad(){const d=await json('../sitecreator-api.php',{cache:'no-store'});files=d.files||{};$('permission').hidden=d.permission==='approved';$('save').disabled=d.permission!=='approved';$('generate').disabled=d.permission!=='approved'||!CHAT;if(d.site){$('site-name').value=d.site.name;$('public-url').href=d.site.url;$('public-url').textContent=d.site.url;$('status').textContent='Сайт опубликован'}else $('status').textContent='Сайт ещё не опубликован';const first=files['index.html']?'index.html':files['index.php']?'index.php':Object.keys(files)[0];if(first){$('path').value=first;$('editor').value=files[first]}return d}async function chatApi(action,data={},post=false){return json('../api.php?action='+encodeURIComponent(action)+(post?'':'&'+new URLSearchParams(data)),post?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(data)}:{cache:'no-store'})}async function initChat(){if(!CHAT)return;const d=await chatApi('messages',{chat_id:CHAT,after:0});for(const m of d.messages||[])last=Math.max(last,Number(m.id));editCursor=Number(d.edit_cursor||0)}async function ai(){const prompt=$('prompt').value.trim();if(!prompt)return $('error').textContent='Опишите будущий сайт.';busy=true;$('generate').disabled=true;$('output').innerHTML='<span class="spinner"></span> ИИ создаёт и публикует сайт…';try{await chatApi('message.send',{chat_id:CHAT,body:'/site-ai '+prompt,nonce:nonce()},true);let target=0;for(let i=0;i<120;i++){const d=await chatApi('messages',{chat_id:CHAT,after:last,edit_after:editCursor});editCursor=Number(d.edit_cursor||editCursor);for(const m of d.messages||[]){last=Math.max(last,Number(m.id));if(Number(m.user_id)!==ME){target=Number(m.id);$('output').textContent=m.body}}for(const e of d.edited_messages||[]){if(!target||Number(e.message_id)===target){$('output').textContent=e.body;if(/^[✅❌]/.test(e.body)){busy=false;break}}}if(!busy)break;await new Promise(r=>setTimeout(r,1500))}if(busy)throw Error('ИИ отвечает слишком долго. Результат появится в чате @compilerbot.');await siteLoad()}catch(e){$('error').textContent=e.message}finally{busy=false;$('generate').disabled=false}}async function importFiles(list){for(const file of list){const path=(file.webkitRelativePath||file.name).replace(/^[^/]+\//,'');if(!/^[A-Za-z0-9][A-Za-z0-9._\/-]{0,179}$/.test(path)||!/\.(html?|css|js|json|txt|svg|php)$/i.test(path))continue;files[path]=await file.text()}const names=Object.keys(files);$('file-count').textContent=names.length?'Файлов: '+names.length:'Подходящих файлов нет';if(names.length){$('path').value=names[0];$('editor').value=files[names[0]]}}async function save(){try{files[$('path').value.trim()]=$('editor').value;$('status').textContent='Публикация…';const d=await json('../sitecreator-api.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action:'save',name:$('site-name').value,files})});$('status').textContent='Сайт опубликован';$('public-url').href=d.site.url;$('public-url').textContent=d.site.url;$('error').textContent=''}catch(e){$('error').textContent=e.message}}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$('ai-mode').hidden=b.dataset.tab!=='ai';$('upload-mode').hidden=b.dataset.tab!=='upload'});$('generate').onclick=ai;$('pick-files').onclick=()=>$('files-input').click();$('pick-folder').onclick=()=>$('folder-input').click();$('files-input').onchange=()=>importFiles($('files-input').files);$('folder-input').onchange=()=>importFiles($('folder-input').files);$('open-file').onclick=()=>{$('editor').value=files[$('path').value.trim()]||''};$('new-file').onclick=()=>{$('path').value='';$('editor').value='';$('path').focus()};$('save').onclick=save;$('delete').onclick=async()=>{if(!confirm('Удалить постоянный сайт и все файлы?'))return;try{await json('../sitecreator-api.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action:'delete'})});files={};$('status').textContent='Сайт удалён'}catch(e){$('error').textContent=e.message}};Promise.all([siteLoad(),initChat()]).catch(e=>$('error').textContent=e.message);</script><script src="../assets/creator-enhance.js?v=20261102-prompt1"></script></body></html>
